// block_graphical_events/chart_module.js
define(['core/toast','chart'], function(addToast,Chart) {
    return {
        init: function(data) {
          createLineChart(data);
            
        }
    };
});

const createLineChart=(data)=>{
  //Grafica que muestra el número de tickets (abiertos, cerrados, erroneos y asignados) por dotación
  const ctx = document.getElementById('myLineChart');
            
            
  window.console.log(data);
  const labels = getCenteredMonthsCurrentYear(12);

  // Create the chart
  new Chart(ctx, {
      type: 'line',
      data: {
          labels: labels,
          datasets: [
                {
                  label: 'C1',
                  data: [100,23,33,44,44,55,60],
                  backgroundColor: [
                    'rgba(255, 99, 132, 0.4)',
                    ],
                  borderColor: [
                    'rgba(255, 99, 132, 1)',
                    ],
                },
                {
                  label: 'C2',
                  data: [50,80,90,49,49,64,100],
                  backgroundColor: [
                    'rgba(54, 162, 235, 0.4)',
                    ],
                  borderColor: [
                    'rgba(54, 162, 235, 1)',
                    ],
              },
                
          ]
      },
      options: {
          scales: {
              y: {
                  beginAtZero: true
              }
          },
          responsive: true,
          plugins: {
            legend: {
              position: 'top',
            },
            title: {
              display: true,
              text: 'Response time average to close a ticket'
            }
          }
      }
  });
}




